import { useAuth } from '../lib/auth'
import { useHealth } from '../lib/health'
import { Icon } from './ui/ui'

export function Wordmark() {
  return (
    <a className="logo" href="#/" aria-label="EARWITNESS home">
      <svg width="26" height="26" viewBox="0 0 32 32" aria-hidden>
        <path d="M2 16 C8 6 24 6 30 16 C24 26 8 26 2 16 Z" fill="none" stroke="#ededed" strokeWidth="2" />
        <path d="M9 16 h3 l2 -5 l3 10 l2 -5 h4" fill="none" stroke="#db2828" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
      <span>
        EAR<b>WITNESS</b>
      </span>
    </a>
  )
}

export function Header({ route }: { route: string }) {
  const { health, offline } = useHealth()
  const auth = useAuth()
  const nav = [
    { href: '#/', key: 'home', label: 'Cases', icon: 'folder-open', accent: 'blue' },
    { href: '#/examine', key: 'examine', label: 'Examine', icon: 'magnifying-glass', accent: 'red' },
    { href: '#/how', key: 'how', label: 'How it works', icon: 'circle-question', accent: 'green' },
  ]
  return (
    <header className="top">
      <div className="wrap">
        <Wordmark />
        <nav className="nav">
          {nav.map((n) => (
            <a key={n.key} href={n.href} className={`c-${n.accent} ${route === n.key ? 'active' : ''}`}>
              <Icon name={n.icon} />
              {n.label}
            </a>
          ))}
        </nav>
        <div className="top-right">
          {offline ? (
            <span className="status-pill c-red" data-tip="The analysis server is not reachable. Start it with: uv run earwitness serve">
              <i className="status-dot" /> Server offline
            </span>
          ) : (
            health && (
              <span
                className={`status-pill ${health.openai ? 'c-purple' : 'c-grey'}`}
                data-tip={
                  health.openai
                    ? 'AI checks are on: speech, the AI eyewitness and location-from-pixels run, and their results are labelled AI.'
                    : 'AI checks are off. Every result comes from measured checks only.'
                }
              >
                <Icon name="robot" /> AI {health.openai ? 'on' : 'off'}
              </span>
            )
          )}
          {health && (
            <span className="status-pill c-green" data-tip={`${health.modules.length} checks run on every video, ${health.image_modules?.length ?? 0} on every photo`}>
              <i className="status-dot on" /> {health.modules.length + (health.image_modules?.length ?? 0)} checks ready
            </span>
          )}
          {auth.enabled &&
            !auth.loading &&
            (auth.user ? (
              <button
                className="status-pill c-blue auth-btn"
                onClick={auth.logout}
                data-tip={`Logged in as ${auth.user.email ?? auth.user.name}. Click to log out.`}
              >
                <Icon name="right-from-bracket" /> {auth.user.name ?? auth.user.email ?? 'Log out'}
              </button>
            ) : (
              <button
                className="status-pill c-blue auth-btn"
                onClick={auth.login}
                data-tip="Log in to upload, re-run or delete cases. Viewing needs no login."
              >
                <Icon name="right-to-bracket" /> Log in
              </button>
            ))}
        </div>
      </div>
    </header>
  )
}
                </div>
                <small className="faint">For large files: no upload needed.</small>
              </label>
            </div>
          </details>
          {err && (
            <Alert icon="triangle-exclamation" tone="red" title="That did not work">
              {err}
            </Alert>
          )}

          <SectionTitle icon="box-archive" accent="blue" small={cases ? `${cases.length} on file` : undefined}>
            Recent cases
          </SectionTitle>
          {cases === null ? (
            <div className="cards">
              {[0, 1, 2].map((i) => (
                <div className="card" key={i}>
                  <div className="card-img" />
                  <div className="card-body">
                    <Redacted lines={3} />
                  </div>
                </div>
              ))}
            </div>
          ) : cases.length === 0 ? (
            <Empty icon="folder-open">No cases yet. Examine a video or photo to open the first file.</Empty>
          ) : (
            <div className="cards">
              {cases.map((c) => (
                <CaseCard key={c.id} c={c} verdict={verdictFor(c)} summary={c.summary_plain ?? meta[c.id]?.summary ?? null} onDelete={() => remove(c)} />
              ))}
            </div>
          )}
        </div>

        <aside className="home-side">
          <SectionTitle icon="flag-checkered" accent="green">
            Getting started
          </SectionTitle>
          <ul className="links panel c-green">
            <li>
              <button onClick={() => fileInput.current?.click()}>
                Examine your first file <small>MP4, MOV, JPEG, HEIC, PNG…</small>
              </button>
            </li>
            <li>
              <a href="#/how">
                What each check does <small>plain English</small>
              </a>
            </li>
            <li>
              <a href="#/how#verdict">
                How to read a verdict <small>strong vs weak</small>
              </a>
            </li>
            <li>
              <a href="#/how#limits">
                What it cannot prove <small>read this</small>
              </a>
            </li>
          </ul>

          <SectionTitle icon="eye" accent="red">
            What it can detect
          </SectionTitle>
          <ul className="detect panel c-red">
            {[...(health?.modules ?? []), ...(health?.image_modules ?? []).filter((m) => !(health?.modules ?? []).some((v) => v.name === m.name && v.title === m.title))].map((m) => {
              const p = modulePlain(m.name, m.title)
              return (
                <li key={`${m.kind ?? 'video'}:${m.name}`} className={`c-${p.accent}`} data-tip={p.does}>
                  <Icon name={p.icon} />
                  <div>
                    <b>
                      {p.name}
                      {m.kind === 'image' && <small className="kind-tag">photo</small>}
                    </b>
                    <span className="muted small">{p.reveals || m.description}</span>
                  </div>
                </li>
              )
            })}
            {!health && (
              <li>
                <Redacted lines={4} />
              </li>
            )}
          </ul>
        </aside>
      </div>
    </main>
  )
}

